DO $$
DECLARE r record; v_rows bigint; v_count bigint; v_t timestamptz;
BEGIN
  PERFORM set_config('search_path', 'opera, public', true);
  FOR r IN
    SELECT p.business_unit, p.settlement_date, p.published_run_id, rr.resolved_settlement_date
    FROM opera.recon_snapshot_pointer p
    JOIN opera.recon_refresh_run rr ON rr.uuid = p.published_run_id
    WHERE p.tenant_id = '227cd5f5-4498-4dba-bda9-05b8edc41113' AND p.business_unit = 'CFS' AND p.view_type = 'SETTLE_PRICING'
      AND p.settlement_date = (SELECT max(p2.settlement_date) FROM opera.recon_snapshot_pointer p2
                               WHERE p2.tenant_id = p.tenant_id AND p2.business_unit = p.business_unit AND p2.view_type = p.view_type)
  LOOP
    IF EXISTS (SELECT 1 FROM opera.recon_settle_snapshot s JOIN opera.latest_active_lot l
                 ON l.tenant_id = s.tenant_id AND l.business_unit = s.business_unit AND l.trade_id = coalesce(s.source_trade_id, regexp_replace(s.trade_id, '-CFS$', ''))
               WHERE s.run_id = r.published_run_id AND s.tenant_id = '227cd5f5-4498-4dba-bda9-05b8edc41113' AND s.business_unit = 'CFS'
                 AND NOT EXISTS (SELECT 1 FROM parity_work.change_lal_uat_02_fill_fill_all_bus_20261119160510 b
                                 WHERE b.tenant_id = l.tenant_id AND b.business_unit = l.business_unit AND b.trade_id = l.trade_id)) THEN
      RAISE NOTICE 'CFS SETTLE_PRICING % already holds trades added by the fill: skipped', r.settlement_date;
      CONTINUE;
    END IF;
    IF NOT pg_try_advisory_xact_lock(hashtextextended('227cd5f5-4498-4dba-bda9-05b8edc41113' || '|CFS|SETTLE_PRICING|' || r.resolved_settlement_date::text, 0)) THEN
      RAISE EXCEPTION 'the app is refreshing CFS SETTLE_PRICING for %: try again later', r.settlement_date;
    END IF;
    v_t := clock_timestamp();
    v_rows := opera.recon_materialize_settle(r.published_run_id);
    PERFORM opera.recon_postprocess_settle(r.published_run_id);
    SELECT count(*) INTO v_count FROM opera.recon_settle_snapshot
     WHERE run_id = r.published_run_id AND tenant_id = '227cd5f5-4498-4dba-bda9-05b8edc41113' AND business_unit = 'CFS' AND settlement_date = r.resolved_settlement_date;
    IF v_rows IS DISTINCT FROM v_count THEN
      RAISE EXCEPTION 'validation failed for CFS SETTLE_PRICING: materialised %, persisted %', v_rows, v_count;
    END IF;
    UPDATE opera.recon_refresh_run SET row_count = v_rows, updated_timestamp = now() WHERE uuid = r.published_run_id;
    RAISE NOTICE 'CFS SETTLE_PRICING %: % rows in % s', r.settlement_date, v_rows, round(extract(epoch FROM clock_timestamp() - v_t)::numeric, 1);
  END LOOP;
  IF NOT FOUND THEN
    RAISE NOTICE 'CFS SETTLE_PRICING: no published snapshot, nothing to refresh (skipped)';
  END IF;
END $$

